SELECT CASE WHEN s.risk_reward_ratio < 1 THEN 'rr<1' ELSE 'rr>=1' END AS rr_band, CASE WHEN m.entry_quality_score < 55 THEN 'eq50-54' WHEN m.entry_quality_score < 70 THEN 'eq55-69' ELSE 'eq70+' END AS eq_band, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY rr_band, eq_band ORDER BY rr_band, eq_band